llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Delpazolid (LCB01-0371) had a mean absolute oral bioavailability of 99.75% in humans after an 800 mg oral dose versus IV, demonstrating near-complete absorption for a small-molecule drug with a basic amine and polar heteroaromatic features; this strongly supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib, which shares piperidine/aminopyrimidine/aniline-like architecture with the query, had an estimated oral bioavailability of 46% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tolvaptan had a mean absolute oral bioavailability of 56% (range 42-80%) in healthy subjects after a 30 mg oral tablet versus IV, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Sildenafil had an absolute oral bioavailability of 41% (90% CI 35.6-47.3) after 50 mg PO versus IV in healthy subjects; despite first-pass metabolism, F remains above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amsacrine, the lowest retrieved human oral bioavailability value, was 32%, still above the 20% threshold, indicating that even the least-absorbed analogue supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Prasugrel had an oral bioavailability of about 79% in humans, supporting high F for a lipophilic small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "S-RCP solution had an absolute oral bioavailability of 65% in humans, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Rufloxacin had a urinary recovery indicating oral bioavailability of at least 50% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues with high assay-transfer scores have human oral bioavailability values of 32-100%, all above the 20% threshold; no contradictory evidence was retrieved, so the query is predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "No IV/oral crossover data for the query; absolute F is inferred from analogues.",
    "Potential food effects, formulation dependence, and first-pass metabolism for the query are not directly characterized.",
    "Some retrieved records are not strictly absolute bioavailability (e.g., urinary recovery, qualitative descriptions), but they are supportive and not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

